div.toast {
    overflow: visible !important;
    position: relative !important;
    top: 25px !important;
    margin: 10px auto !important;
    width: 310px !important;
    min-height: 45px;
    background-color: rgba(244, 241, 239, 0.5) !important;
    backdrop-filter: blur(3px) !important;
    border: 2px solid white !important;
    border-radius: 0px !important;
    box-shadow:
        0 0 0 1px #D8D1D0,
        0 4px 15px rgba(216, 209, 208, 0.3) !important;
    padding: 15px 15px 15px 50px !important;
    color: #9F928F !important;
}

.toast-title {
    color: #8B807D !important;
    font-weight: bold !important;
    margin-bottom: 4px !important;
}

div.toast::before {
    content: "";
    position: absolute;
    top: 50%;
    left: 20px;
    transform: translateY(-50%) rotate(-8deg);
    width: 48px;
    height: 48px;
    background-image: url('链接📮');
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    filter: drop-shadow(2px 2px 2px rgba(225, 182, 194, 0.3));
}



